  const write = run;
  writes.add(write);
  void write.then(
    () => {
      writes.delete(write);
    },
    () => {
      // A refused batch means the session is gone; release the camera with it.
      writes.delete(write);
      reportEnded('storage');
      void shutdown();
    },
  );
}

